node.doctext:
Hello Esteemed monks! The below code works fine under windows vista....however it does not work fine under windows 7. Now I can send the commands just fine and it works connecting to the Arduino.....the issue is the messages from the Incoming Data are not being received... I disabled ALL network blocks so its sending the info just not receiving. Thanks in advanced and thanks to roboticus for helping so far.

<code>

#!/usr/bin/perl -w
######################
#
# VARIABLES, 
# PACKAGES, & DEFINES
#
######################
use strict;
use warnings;
use diagnostics;
use Term::ReadKey;
use Win32::Console::ANSI qw/ Title SetCloseButton Cursor :SW_ /;
use Win32::Console::ANSI;
use Win32::Console;
use Term::ANSIColor;
use Term::ANSIScreen qw/:cursor :screen/;

##########################
#
# SET TERMINAL ATTRIBUTES
#
##########################

$SIG{INT}= 'IGNORE'; 
SetCloseButton(0);
ShowConsoleWindow(SW_SHOWMAXIMIZED);

####################################
#
# LOGGING KEY STROKE TIME STAMP SUB
#
####################################

my $time = localtime(time); # ADD TIME STAMP TO LOGFILE

##################
#
# SET SERIAL PORT
#
##################

use Win32::SerialPort;
my $port = Win32::SerialPort->new("COM7") or die "Open Port Failed. $!\n";
$port->is_rs232;

# SET UP THE SERIAL PORT
# 9600 OR 19200, 81N ON THE USB FTDI DRIVER

$port->initialize();
$port->baudrate(9600);
$port->databits(8);
$port->parity("none");
$port->stopbits(1);
$port->write_settings || undef $port;

##################
#
# MAIN SCREEN SUB
#
##################

no warnings 'numeric';

Title "Simple Signals Driver";
print colored("CONNECTING TO SIGNAL SYSTEM...", 'bold green'), "\n";
sleep(15);
print "\n", colored("CONNECTED...",'bold green'), "\n", colored("STARTING RELAY SIGNAL PROGRAM", 'bold green'), "\n\n";

# Buffer used to build our command line
my $command_line = "";

# Buffer for our serial data
my @serial_data = ();

# Put console into raw mode
ReadMode 4;

setup_serial_interface();

my $are_we_done_yet = 0;
while (!$are_we_done_yet) {
my $con_key = ReadKey(-1);
if (defined $con_key) {
if ($con_key eq "\r" or $con_key eq "\n") {
# user finished entering the command
handle_command($command_line);
$command_line = "";
} else {
            # Not end of line, so add to command line.
            # NOTE: you'll want to handle backspace and/or
            # other line editing commands.  But that's too
            # much work for a quick demo...
$command_line .= $con_key;
}
} elsif (is_serial_data_ready()) {
        # Serial device gave us something to do
handle_serial_data();
} else {

}
}

ReadMode(0); # RESTORE CONSOLE MODE

#################
#
# HANDLE COMMAND
#
#################

sub handle_command {
my $cmd = shift;
if ($cmd =~ /^q/i) {
print "\n", colored("QUIT PROGRAM!", 'bold yellow'), "\n";
$are_we_done_yet = 1;
$port->purge_all;
$port->close or die "CLOSE FAILED: $!\n";
undef $port;                               # CLOSES PORT FREES MEMORY
sleep(3);
} elsif ($cmd =~ /^\d+$/i) {
print colored("\nSENDING COMMAND $cmd $time...", 'bold yellow'), "\n\n";
$port->write("$cmd\r");
$port->lookclear();
print colored("DONE!", 'bold yellow'), "\n\n";
} else {
print colored("UNKNOWN COMMAND: $cmd", 'bold red'), "\n";
} # END ELSE
} # END HANDLE COMMAND

#############################
#
# USB/SERIAL/INTERFACE WITH
# THE ARDUINO
#
#############################

sub setup_serial_interface {
my $seconds_per_transmission = 1.5;
$SIG{ALRM} = sub {
push @serial_data, rand;
alarm $seconds_per_transmission;
};       # ALARM SUB
alarm(3); # LOOK FOR PACKET DATA
}        # END SUB

sub is_serial_data_ready {
return scalar @serial_data;
} # END SUB

sub handle_serial_data {
my $c = $port->input; # non-blocking read
#$c =~ s/r/\n/;
print colored("Incoming Data:", 'bold green'), colored("$c", 'bold yellow'), "\n";
#print "Incoming Data: $c(", join(", ", @serial_data), ")\n";
@serial_data = ();
} # END SUB

</code>
